import test from "node:test"; import assert from "node:assert/strict"; import fs from "node:fs"; import { availabilityProbability, buildCandidateBoard, positionNeedScore, positionOverdraftPenalty, projectedTightEndPriorityTier, sensiblePositionCap, recommendationPositionCap, remainingReplacementDemand, replacementDemand, valueOverReplacement, recommend } from "../core/recommend.js"; import { evaluateDraft, flexibilityOverrideMargin, rankEvaluatedRecommendations, recommendationDominates } from "../core/evaluate.js"; import { fixtureState,shaheedPick128State,shaheedPick128OnClockState } from "./fixture.js";
import { calibrateTitleProbability, createPairedScenario, finishDraft, pairedPlayoffWinner, playoffWinner, projectedTightEndDraftCenters, replacementSpecialistProjection, roundRobinPairs, simulationDraftPool } from "../core/simulate.js";
import { SOURCE_PROFILES, STRATEGIES, snakeSlot } from "../shared/domain.js";
import { regressedSpecialistValue, specialistOpportunity } from "../core/lineup-value.js";
const AVAILABILITY_CONTEXT={season:2026,settings:{teams:10,scoring:{reception:0}}};
test("recommendations contain tuned factors, availability, and weekly lineup diagnostics",()=>{const r=recommend({state:fixtureState(),userSlot:1});assert.equal(r.length,8);assert.ok(r.every(x=>x.drivers.length===3&&x.nextPickAvailability>=0&&x.nextPickAvailability<=1&&x.factors.history>=0&&x.factors.history<=1&&Number.isFinite(x.expectedWeeklyPoints)&&Number.isFinite(x.expectedWeeklyDelta)&&Number.isFinite(x.starterContribution)&&Number.isFinite(x.replacementDelta)))});
test("player board exposes every undrafted player while the simulated shortlist is the strict top eight",()=>{const state=fixtureState({teams:4,rounds:6,picked:7}),board=buildCandidateBoard({state,userSlot:4,strategy:"titleOnly"}),shortlist=recommend({state,userSlot:4,strategy:"titleOnly",limit:8}),eligible=board.filter(row=>row.simulationEligible);assert.ok(board.length>shortlist.length);assert.equal(shortlist.length,8);assert.deepEqual(shortlist.map(row=>row.player.id),eligible.slice(0,8).map(row=>row.player.id));assert.ok(board.some(row=>!row.simulationEligible&&row.exclusionReason));assert.ok(board.every(row=>!state.picks.some(pick=>String(pick.playerId)===String(row.player.id))))});
test("player board retains undrafted players whose projection data is unavailable",()=>{const state=fixtureState({teams:4,rounds:6,picked:0}),player={id:"unprojected-qb",name:"Unprojected Quarterback",position:"QB",team:"FA",mean:0,floor:0,ceiling:0,adp:null,eligibleForRecommendation:false};state.players.push(player);const board=buildCandidateBoard({state,userSlot:1}),row=board.find(item=>item.player.id===player.id);assert.ok(row);assert.equal(row.simulationEligible,false);assert.equal(row.exclusionReason,"Projection data is not available for this player yet.");assert.deepEqual(row.sourceProjections,{sleeper:null,espn:null,yahoo:null,fantasyPros:null,owned:null})});
test("a fallback range without a positive mean is not usable projection data",()=>{const state=fixtureState({teams:4,rounds:6,picked:0}),player={id:"stale-qb",name:"Stale Catalog Quarterback",position:"QB",team:"FA",mean:0,floor:0,ceiling:52.94,adp:null,eligibleForRecommendation:false};state.players.push(player);const board=buildCandidateBoard({state,userSlot:1}),row=board.find(item=>item.player.id===player.id);assert.ok(row);assert.equal(row.simulationEligible,false);assert.equal(row.exclusionReason,"Projection data is not available for this player yet.")});
test("player board exposes the live draft-site and owned projections outside the consensus source list",()=>{const state=fixtureState({teams:4,rounds:6,picked:0}),player=state.players[0];state.platform="espn";player.platformProjection=211;player.draftGoblinProjection=207;player.projectionConsensus={points:209,sources:[]};const [row]=buildCandidateBoard({state,userSlot:1}).filter(item=>item.player.id===player.id);assert.equal(row.sourceProjections.espn,211);assert.equal(row.sourceProjections.owned,207);state.platform="sleeper";const [sleeperRow]=buildCandidateBoard({state,userSlot:1}).filter(item=>item.player.id===player.id);assert.equal(sleeperRow.sourceProjections.sleeper,211);assert.equal(sleeperRow.sourceProjections.espn,null);state.platform="yahoo";const [yahooRow]=buildCandidateBoard({state,userSlot:1}).filter(item=>item.player.id===player.id);assert.equal(yahooRow.sourceProjections.yahoo,211);assert.equal(yahooRow.sourceProjections.espn,null)});
test("a slightly dominated number-two candidate remains in the strict simulated eight",()=>{const state=fixtureState({teams:4,rounds:6,picked:0});state.settings.slots={QB:1,RB:2,WR:2,TE:1,FLEX:1,K:0,DST:0,BENCH:1};state.players=Array.from({length:12},(_,index)=>({id:`c${index}`,name:`Candidate ${index}`,position:index%2?"WR":"RB",team:"T",mean:300-index,ceiling:360-index,floor:240-index,risk:.3,scarcity:.5,adp:index+1,adpSd:6,eligibleForRecommendation:true}));const board=buildCandidateBoard({state,userSlot:1,strategy:"projection"}),eligible=board.filter(row=>row.simulationEligible),shortlist=recommend({state,userSlot:1,strategy:"projection",limit:8});assert.ok(eligible[0].player.mean>eligible[1].player.mean&&eligible[0].player.floor>eligible[1].player.floor&&eligible[0].player.ceiling>eligible[1].player.ceiling);assert.equal(shortlist[1].player.id,eligible[1].player.id)});
test("default strategies do not apply an unvalidated historical roster prior",()=>{assert.equal(STRATEGIES.balanced.history,0);assert.equal(SOURCE_PROFILES.projectionLed.history,0)});
test("title-only ties use an explicit championship-tail policy",()=>{assert.ok(STRATEGIES.titleOnly);assert.ok(STRATEGIES.titleOnly.ceiling>STRATEGIES.balanced.ceiling);assert.ok(STRATEGIES.titleOnly.risk>0);assert.ok(STRATEGIES.titleOnly.floor<STRATEGIES.balanced.floor)});
test("pick 15 title-only tiebreak materially upgrades Love's asymmetric ceiling versus Brown's floor",()=>{const settings={teams:12,rounds:16,slots:{QB:1,RB:2,WR:2,TE:1,FLEX:1,K:0,DST:0,BENCH:9}},player=(id,name,position,mean,floor,ceiling,risk,scarcity,adp)=>({id,name,position,mean,floor,ceiling,risk,scarcity,adp,adpSd:8,eligibleForRecommendation:true}),lamb=player("lamb","CeeDee Lamb","WR",280,225,390,.35,.55,10),brown=player("brown","Chase Brown","RB",267.86,231.03,358.26,.25,.8,25),love=player("love","Jeremiyah Love","RB",248.42,150.05,373.13,.72,.8,14),players=[lamb,brown,love,player("rice","Rashee Rice","WR",255.11,142.86,390.32,.8,.55,17),player("hampton","Omarion Hampton","RB",254.12,186.33,360.79,.485,.8,20),player("qb","Josh Allen","QB",367.5,311,495,.279,.6,15),player("te","Trey McBride","TE",250.25,215.84,334.71,.25,.7,22),...Array.from({length:20},(_,index)=>player(`depth-${index}`,`Depth ${index}`,index%2?"RB":"WR",220-index*3,155-index*2,305-index*2,.4,index%2?.8:.55,30+index))],picks=Array.from({length:14},(_,index)=>({pickNo:index+1,playerId:index===9?lamb.id:`taken-${index+1}`,slot:snakeSlot(index+1,12)})),state={platform:"fixture",draftId:"love-brown-title-tail",projectionSeason:2026,settings,players,picks},margin=strategy=>{const ranked=recommend({state,userSlot:10,strategy,sourceProfile:"projectionLed",limit:8}),loveRow=ranked.find(item=>item.player.id===love.id),brownRow=ranked.find(item=>item.player.id===brown.id);assert.ok(loveRow&&brownRow);return loveRow.planScore-brownRow.planScore};assert.ok(margin("titleOnly")>margin("balanced")+.15)});
test("ranking emphasis labels match their actual projection and ADP direction",()=>{assert.ok(SOURCE_PROFILES.ownedModel.projection>SOURCE_PROFILES.projectionLed.projection);assert.ok(SOURCE_PROFILES.ownedModel.availability<SOURCE_PROFILES.projectionLed.availability);assert.ok(SOURCE_PROFILES.marketLed.availability>SOURCE_PROFILES.projectionLed.availability);assert.ok(SOURCE_PROFILES.marketLed.projection<SOURCE_PROFILES.projectionLed.projection)});
test("simulation is deterministic and bounded",()=>{const input={state:fixtureState(),userSlot:1,iterations:50,seed:10};const a=evaluateDraft(input),b=evaluateDraft(input);assert.deepEqual(a,b);assert.ok(a.every(x=>x.simulation.championshipProbability>=0&&x.simulation.championshipProbability<=1))});
test("live recommendations expose a 10000-simulation-equivalent final title projection without changing calibrated ranking odds",()=>{const item=evaluateDraft({state:fixtureState(),userSlot:1,iterations:120,seed:10,strategy:"upside"})[0],simulation=item.simulation,expected=(simulation.rawChampionshipProbability*10000+simulation.priorStrength*simulation.priorProbability)/(10000+simulation.priorStrength);assert.equal(simulation.projectedFinalChampionshipProbability,Math.round(expected*1000)/1000);assert.notEqual(simulation.projectedFinalChampionshipProbability,undefined);assert.ok(Number.isFinite(simulation.rankingChampionshipProbability))});
