test("off-turn preparation shows availability at the immediate upcoming user pick",()=>{const result=recommend({state:fixtureState({teams:4,picked:1}),userSlot:1});assert.ok(result.every(x=>x.waitingForUserPick&&x.nextUserPick===8&&x.availabilityTargetPick===8));assert.ok(result.every(x=>Number.isFinite(x.planScore)))});
