test("back-to-back snake picks have certain availability after passing",()=>{const state=fixtureState({teams:12,rounds:6,picked:35}),result=recommend({state,userSlot:12,limit:100});assert.ok(result.length>0);assert.ok(result.every(x=>!x.waitingForUserPick&&x.nextUserPick===36&&x.availabilityTargetPick===37&&x.nextPickAvailability===1))});
