test("source profiles materially change balanced recommendation scores",()=>{const state=fixtureState(),projection=recommend({state,userSlot:1,sourceProfile:"ownedModel",limit:100}),market=recommend({state,userSlot:1,sourceProfile:"marketLed",limit:100}),marketById=new Map(market.map(x=>[x.player.id,x.score]));assert.ok(projection.some(x=>Math.abs(x.score-marketById.get(x.player.id))>.01))});
