test("advanced custom weights materially change the recommendation data",()=>{const state=fixtureState({picked:0}),steady=state.players.find(player=>player.position==="RB"),volatile=state.players.find(player=>player.position==="RB"&&player!==steady);Object.assign(steady,{mean:300,floor:250,ceiling:320,risk:.1,performanceRisk:.1,adp:1});Object.assign(volatile,{mean:230,floor:100,ceiling:500,risk:.9,performanceRisk:.9,adp:2});const only=key=>({projection:0,ceiling:0,floor:0,scarcity:0,need:0,availability:0,history:0,risk:0,[key]:1}),projection=recommend({state,userSlot:1,strategy:"custom",customWeights:only("projection"),limit:100}),ceiling=recommend({state,userSlot:1,strategy:"custom",customWeights:only("ceiling"),limit:100});assert.ok(projection.indexOf(projection.find(row=>row.player.id===steady.id))<projection.indexOf(projection.find(row=>row.player.id===volatile.id)));assert.ok(ceiling.indexOf(ceiling.find(row=>row.player.id===volatile.id))<ceiling.indexOf(ceiling.find(row=>row.player.id===steady.id)));const projectionById=new Map(projection.map(row=>[row.player.id,row.planScore]));assert.ok(ceiling.some(row=>Math.abs(row.planScore-projectionById.get(row.player.id))>.1))});
test("projection-only custom weights follow displayed season points across positions without hidden policy adjustments",()=>{const state=fixtureState({teams:4,rounds:6,picked:0}),lamb=state.players.find(player=>player.position==="WR"),jeanty=state.players.find(player=>player.position==="RB");Object.assign(lamb,{mean:269.7,floor:236,ceiling:318,adp:10});Object.assign(jeanty,{mean:263.8,floor:229,ceiling:312,adp:11});const weights={projection:.6,ceiling:0,floor:0,scarcity:0,need:0,availability:0,history:0,risk:0},ranked=recommend({state,userSlot:1,strategy:"custom",customWeights:weights,limit:100}),lambRow=ranked.find(row=>row.player.id===lamb.id),jeantyRow=ranked.find(row=>row.player.id===jeanty.id);assert.ok(lambRow&&jeantyRow);assert.ok(lambRow.factors.projection>jeantyRow.factors.projection);assert.equal(lambRow.planScore,.6*lambRow.factors.projection);assert.equal(jeantyRow.planScore,.6*jeantyRow.factors.projection);assert.ok(ranked.indexOf(lambRow)<ranked.indexOf(jeantyRow))});
test("won't-reach custom weight rewards on-clock draft risk and stays display-only off turn",()=>{const state=fixtureState({teams:4,rounds:6,picked:0});state.projectionSeason=2026;const fragile=state.players[0],likely=state.players[1];for(const player of [fragile,likely])Object.assign(player,{mean:250,floor:190,ceiling:310,risk:.3,scarcity:.4});Object.assign(fragile,{id:"fragile",name:"Fragile",adp:1,adpSd:4});Object.assign(likely,{id:"likely",name:"Likely",adp:50,adpSd:8});const weights={projection:0,ceiling:0,floor:0,scarcity:0,need:0,availability:.6,history:0,risk:0},onClock=recommend({state,userSlot:1,strategy:"custom",customWeights:weights,limit:100}),fragileRow=onClock.find(row=>row.player.id==="fragile"),likelyRow=onClock.find(row=>row.player.id==="likely");assert.ok(fragileRow&&likelyRow);assert.ok(fragileRow.factors.availability>likelyRow.factors.availability);assert.equal(fragileRow.planScore,.6*fragileRow.factors.availability);assert.ok(onClock.indexOf(fragileRow)<onClock.indexOf(likelyRow));state.picks=[{pickNo:1,playerId:state.players.at(-1).id,slot:1}];const offTurn=recommend({state,userSlot:1,strategy:"custom",customWeights:weights,limit:100});assert.ok(offTurn.every(row=>row.factors.availability===0))});
