test("recommendations treat a platform-id pick as the canonical drafted player",()=>{const state=fixtureState({teams:4,rounds:6,picked:1}),canonical=state.players.find(player=>String(player.id)===String(state.picks[0].playerId));canonical.platformPlayerId="espn-picked-player";state.picks[0].playerId="espn-picked-player";const ranked=recommend({state,userSlot:state.picks[0].slot,limit:100});assert.equal(ranked.some(item=>item.player.id===canonical.id),false);assert.equal(remainingReplacementDemand(canonical.position,state),Math.max(0,replacementDemand(canonical.position,state.settings)-1))});
