test("paired six-team playoffs keep seeds one and two out of the wildcard round",()=>{const calls=[],scenario={normal:(phase,round,team)=>{calls.push([phase,round,team]);return 0}},winner=pairedPlayoffWinner([0,1,2,3,4,5],[1000,900,1,1,1,1],scenario),wildcardTeams=new Set(calls.filter(([,round])=>round===0).map(([, ,team])=>team));assert.ok([0,1].includes(winner));assert.deepEqual([...wildcardTeams].sort((a,b)=>a-b),[2,3,4,5])});
