test("title calibration respects 8, 10, 12, and 14 team baselines",()=>{for(const teams of [8,10,12,14]){const result=calibrateTitleProbability({wins:0,iterations:300,teams,progress:0});assert.equal(result.priorProbability,1/teams);assert.ok(result.championshipProbability>0);assert.ok(result.championshipProbability<1/teams)}const probabilities=[8,10,12,14].map(teams=>calibrateTitleProbability({wins:30,iterations:300,teams,progress:0}).championshipProbability);for(let i=1;i<probabilities.length;i++)assert.ok(probabilities[i]<probabilities[i-1])});
test("early one-QB rosters penalize but still expose QBs when explicitly filtered",()=>{const state=fixtureState(),qb=state.players.find(p=>p.position==="QB");state.picks=[{pickNo:1,playerId:qb.id,slot:1}];const result=recommend({state,userSlot:1,positions:["QB"],limit:100});assert.ok(result.length>0);assert.ok(result.every(x=>x.duplicateStarterPenalty>0))});
test("maximum upside prioritizes an open FLEX over a backup QB",()=>{const state=fixtureState({picked:0}),qb=state.players.find(p=>p.position==="QB");state.picks=[{pickNo:1,playerId:qb.id,slot:1},{pickNo:2,playerId:state.players.find(p=>p.id!==qb.id).id,slot:2}];const result=recommend({state,userSlot:1,strategy:"upside",limit:8});assert.ok(result.some(x=>["RB","WR","TE"].includes(x.player.position)));assert.ok(result.filter(x=>x.player.position==="QB").length<=1);assert.ok(result.filter(x=>x.player.position==="QB").every(x=>x.rosterPriorityMultiplier===.28))});
