test("position need prioritizes empty starters then FLEX then useful depth",()=>{const slots={QB:1,RB:2,WR:2,TE:1,FLEX:1,K:1,DST:1,BENCH:6};assert.equal(positionNeedScore("RB",{RB:1},slots,{FLEX:1}),1);assert.equal(positionNeedScore("WR",{WR:2},slots,{FLEX:1}),.72);assert.equal(positionNeedScore("QB",{QB:1},slots,{FLEX:0}),.22);assert.equal(positionNeedScore("QB",{QB:2},slots,{FLEX:0}),0);assert.equal(positionNeedScore("K",{K:1},slots,{FLEX:0}),0);assert.equal(sensiblePositionCap("QB",slots),2);assert.equal(sensiblePositionCap("K",slots),1);assert.equal(recommendationPositionCap("QB",{slots,positionLimits:{QB:1}}),1);assert.equal(recommendationPositionCap("QB",{slots,positionLimits:{QB:4}}),2);assert.ok(sensiblePositionCap("RB",slots)>slots.RB)});
test("RB and WR depth take priority over a backup tight end",()=>{const slots={QB:1,RB:2,WR:2,TE:1,FLEX:1,K:1,DST:1,BENCH:6},needs={FLEX:1},bare={QB:1,RB:2,WR:2,TE:1};assert.equal(positionOverdraftPenalty("TE",bare,slots,needs,9),.34);assert.equal(positionOverdraftPenalty("TE",{...bare,RB:3},slots,needs,9),.20);assert.equal(positionOverdraftPenalty("TE",{...bare,RB:3,WR:3},slots,needs,9),0)});
test("a mid-draft roster with bare RB and WR starters ranks their depth ahead of TE2",()=>{const slots={QB:1,RB:2,WR:2,TE:1,FLEX:1,K:0,DST:0,BENCH:8},make=(id,position,mean=190)=>({id,name:id,position,mean,floor:mean*.75,ceiling:mean*1.25,risk:.3,scarcity:.4,adp:8,adpSd:8,eligibleForRecommendation:true}),roster=[make("QB1","QB",300),make("RB1","RB",230),make("RB2","RB",220),make("WR1","WR",225),make("WR2","WR",215),make("TE1","TE",180)],candidates=[make("RB depth","RB"),make("WR depth","WR"),make("TE depth","TE")],picks=roster.map((player,index)=>({pickNo:index+1,playerId:player.id,slot:1})),ranked=recommend({state:{settings:{teams:10,rounds:15,slots},players:[...roster,...candidates],picks,projectionSeason:2026},userSlot:1,limit:3});assert.ok(["RB","WR"].includes(ranked[0].player.position));assert.equal(ranked.at(-1).player.position,"TE");assert.equal(ranked.at(-1).duplicateStarterPenalty,.34)});
test("strong TE2 value outranks sixth RB or WR after both positions have depth",()=>{const slots={QB:1,RB:2,WR:2,TE:1,FLEX:1,K:1,DST:1,BENCH:6},make=(id,position,mean,adp=130)=>({id,name:id,position,mean,floor:mean*.72,ceiling:mean*1.28,risk:.3,scarcity:.4,adp,adpSd:8,eligibleForRecommendation:true}),roster=[make("QB1","QB",300),...Array.from({length:5},(_,i)=>make(`RB${i+1}`,"RB",220-i*8)),...Array.from({length:5},(_,i)=>make(`WR${i+1}`,"WR",215-i*8)),make("TE1","TE",185)],candidates=[make("Isaiah Likely","TE",156.7,129),make("Keaton Mitchell","RB",96.9,147),make("depth WR","WR",100,148),make("replacement TE","TE",130,160),make("replacement RB","RB",90,161),make("replacement WR","WR",92,162)],picks=Array.from({length:146},(_,index)=>({pickNo:index+1,playerId:index<roster.length?roster[index].id:`taken-${index+1}`,slot:index<roster.length?3:2})),ranked=recommend({state:{settings:{teams:12,rounds:16,slots},players:[...roster,...candidates],picks,projectionSeason:2026},userSlot:3,limit:6});assert.equal(ranked[0].player.name,"Isaiah Likely");assert.equal(ranked[0].duplicateStarterPenalty,.20);assert.equal(ranked[0].factors.need,.48)});
test("filled kicker and defense slots cannot consume general recommendation space",()=>{const state=fixtureState({picked:0});state.settings.slots.K=1;state.settings.slots.DST=1;const kicker=state.players.find(p=>p.position==="K"),defense=state.players.find(p=>p.position==="DST");state.picks=[{pickNo:1,playerId:kicker.id,slot:1},{pickNo:2,playerId:defense.id,slot:1}];const result=recommend({state,userSlot:1,limit:100});assert.equal(result.some(x=>["K","DST"].includes(x.player.position)),false)});test("a second defense is never suggested even through the DST-only filter",()=>{const state=fixtureState({picked:0});state.settings.slots.DST=1;const defense=state.players.find(p=>p.position==="DST");state.picks=[{pickNo:1,playerId:defense.id,slot:1}];assert.deepEqual(recommend({state,userSlot:1,positions:["DST"],limit:100}),[])});
test("kicker and defense are suppressed until the final two rounds",()=>{const state=fixtureState({teams:4,rounds:15,picked:0});state.settings.slots.K=1;state.settings.slots.DST=1;const specialists=recommend({state,userSlot:1,positions:["K","DST"],limit:100});assert.ok(specialists.length>0);assert.ok(specialists.every(item=>item.specialistTimingPenalty>=.6))});
test("late specialists remain visible on the full board without displacing higher-scored simulated candidates",()=>{const state=fixtureState({teams:4,rounds:15,picked:0});state.settings.slots.K=1;state.settings.slots.DST=1;state.picks=Array.from({length:52},(_,index)=>({pickNo:index+1,playerId:`taken-${index}`,slot:2}));const board=buildCandidateBoard({state,userSlot:1}),shortlist=recommend({state,userSlot:1,limit:8});assert.ok(board.some(row=>row.player.position==="K"));assert.ok(board.some(row=>row.player.position==="DST"));assert.deepEqual(shortlist.map(row=>row.player.id),board.filter(row=>row.simulationEligible).slice(0,8).map(row=>row.player.id))});
test("final-round board keeps every missing required position available for comparison",()=>{const state=fixtureState({teams:4,rounds:15,picked:0});state.settings.slots={...state.settings.slots,QB:1,RB:1,WR:1,TE:1,FLEX:0,K:1,DST:1};state.picks=Array.from({length:56},(_,index)=>({pickNo:index+1,playerId:`taken-${index}`,slot:2}));const positions=new Set(buildCandidateBoard({state,userSlot:1}).map(item=>item.player.position));for(const position of ["QB","RB","WR","TE","K","DST"])assert.ok(positions.has(position),`missing ${position}`)});
test("off-turn board uses the user's next pick for specialist availability context",()=>{const state=fixtureState({teams:10,rounds:15,picked:0});state.settings.slots.K=1;state.settings.slots.DST=1;state.picks=Array.from({length:130},(_,index)=>({pickNo:index+1,playerId:`taken-${index}`,slot:index%10+1}));const board=buildCandidateBoard({state,userSlot:1}),specialists=board.filter(row=>["K","DST"].includes(row.player.position));assert.ok(specialists.length>=2);assert.ok(specialists.filter(row=>row.simulationEligible).every(row=>row.nextUserPick===140))});
function completionState({rounds,slots,rosterPositions}){const state=fixtureState({teams:10,rounds,picked:0}),used=new Set();state.settings.slots={...state.settings.slots,...slots};state.picks=rosterPositions.map((position,index)=>{const player=state.players.find(candidate=>candidate.position===position&&!used.has(candidate.id));assert.ok(player,`fixture needs another ${position}`);used.add(player.id);return{pickNo:index+1,playerId:player.id,slot:1}});return state}
test("one pick left and one missing required slot recommends only that position",()=>{const state=completionState({rounds:7,slots:{QB:1,RB:1,WR:1,TE:1,FLEX:0,K:1,DST:1,BENCH:0},rosterPositions:["QB","RB","WR","TE","DST","RB"]}),result=recommend({state,userSlot:1,limit:8});assert.ok(result.length>0);assert.ok(result.every(item=>item.player.position==="K"&&item.rosterCompletionRequired&&item.remainingPicks===1&&item.missingRequiredSlots===1))});
test("three picks left and three missing slots recommends only slot-filling positions",()=>{const state=completionState({rounds:9,slots:{QB:1,RB:1,WR:1,TE:1,FLEX:0,K:1,DST:1,BENCH:2},rosterPositions:["QB","RB","WR","RB","WR","RB"]}),result=recommend({state,userSlot:1,limit:8}),positions=new Set(result.map(item=>item.player.position));assert.ok(result.length>0);assert.ok(result.every(item=>item.rosterCompletionRequired&&["TE","K","DST"].includes(item.player.position)));for(const position of ["TE","K","DST"])assert.ok(positions.has(position),`missing forced ${position}`)});
test("forced K/DST completion overrides a stale incompatible position filter",()=>{const state=completionState({rounds:8,slots:{QB:1,RB:1,WR:1,TE:1,FLEX:0,K:1,DST:1,BENCH:1},rosterPositions:["QB","RB","WR","TE","RB","WR"]}),result=recommend({state,userSlot:1,positions:["RB","WR"],limit:8});assert.ok(result.length>0);assert.ok(result.every(item=>item.rosterCompletionRequired&&["K","DST"].includes(item.player.position)));assert.deepEqual(new Set(result.map(item=>item.player.position)),new Set(["K","DST"]))});
test("a final missing FLEX slot restricts recommendations to FLEX-eligible players",()=>{const state=completionState({rounds:7,slots:{QB:1,RB:1,WR:1,TE:1,FLEX:1,K:1,DST:1,BENCH:0},rosterPositions:["QB","RB","WR","TE","K","DST"]}),result=recommend({state,userSlot:1,limit:8});assert.ok(result.length>0);assert.ok(result.every(item=>item.rosterCompletionRequired&&["RB","WR","TE"].includes(item.player.position)))});
test("position filters rank only the selected positions",()=>{const result=recommend({state:fixtureState(),userSlot:1,positions:["RB","WR"],limit:100});assert.ok(result.length>0);assert.ok(result.every(x=>["RB","WR"].includes(x.player.position)))});
test("positions absent from league settings are never recommended",()=>{const result=recommend({state:fixtureState(),userSlot:1,positions:["K","DST"],limit:100});assert.deepEqual(result,[])});
test("inactive or historical-only players remain reconcilable but are not recommended",()=>{const state=fixtureState(),target=state.players.find(p=>!state.picks.some(pick=>pick.playerId===p.id));target.eligibleForRecommendation=false;assert.equal(recommend({state,userSlot:1,limit:100}).some(item=>item.player.id===target.id),false)});
test("position filters do not change the filter-independent team title estimate",()=>{const state=fixtureState(),rb=evaluateDraft({state,userSlot:1,positions:["RB"],iterations:30}),wr=evaluateDraft({state,userSlot:1,positions:["WR"],iterations:30});assert.ok(rb.length&&wr.length);assert.deepEqual(rb[0].teamSimulation,wr[0].teamSimulation)});
test("the same candidate retains identical raw simulation evidence across filters",()=>{const state=fixtureState(),all=evaluateDraft({state,userSlot:1,limit:100,iterations:30}),rb=evaluateDraft({state,userSlot:1,positions:["RB"],limit:100,iterations:30}),candidate=rb[0],baseline=all.find(item=>item.player.id===candidate.player.id);assert.equal(candidate.simulation.rawProbability,baseline.simulation.rawProbability);assert.equal(candidate.simulation.rawChampionshipProbability,baseline.simulation.rawChampionshipProbability);assert.deepEqual(candidate.simulation.interval,baseline.simulation.interval)});
test("same-position projection dominance cannot be reversed by Monte Carlo noise",()=>{const base={player:{position:"RB"},nextPickAvailability:1,factors:{need:.2},planScore:.4,simulation:{interval:[.02,.18],championshipProbability:.11}},price={...base,player:{position:"RB",mean:151,floor:91,ceiling:227,name:"Jadarian Price"},planScore:.8,simulation:{interval:[.01,.16],championshipProbability:.085}},rodriguez={...base,player:{position:"RB",mean:117.5,floor:79,ceiling:172,name:"Chris Rodriguez"}};assert.equal(recommendationDominates(price,rodriguez),true);const ranked=rankEvaluatedRecommendations([rodriguez,price]);assert.equal(ranked[0].player.name,"Jadarian Price");assert.ok(ranked.every(item=>item.statisticalTie));assert.equal(ranked[0].simulation.displayTitleTenths,ranked[1].simulation.displayTitleTenths);assert.equal(ranked[0].simulation.rankingChampionshipProbability,.085);assert.equal(ranked[1].simulation.rankingChampionshipProbability,.11)});
test("Justice Hill's material same-RB projection edge cannot rank below Dylan Sampson",()=>{const base={nextPickAvailability:1,factors:{need:.42},simulation:{interval:[.07,.10],championshipProbability:.081,rawProbability:.081,iterations:1000}},hill={...base,player:{id:"hill",name:"Justice Hill",position:"RB",mean:79.4,floor:59.5,ceiling:111.9},planScore:.2},sampson={...base,player:{id:"sampson",name:"Dylan Sampson",position:"RB",mean:75,floor:62.3,ceiling:101.8},planScore:.9,simulation:{...base.simulation,championshipProbability:.082,rawProbability:.082}};assert.equal(recommendationDominates(hill,sampson),true);const ranked=rankEvaluatedRecommendations([sampson,hill]);assert.equal(ranked[0].player.name,"Justice Hill");assert.ok(ranked[0].simulation.championshipProbability>=ranked[1].simulation.championshipProbability)});
test("tiny same-position projection differences still defer to the complete ranking model",()=>{const base={nextPickAvailability:1,factors:{need:.42}},slight={...base,player:{position:"RB",mean:101,floor:70,ceiling:125}},safer={...base,player:{position:"RB",mean:100,floor:85,ceiling:130}};assert.equal(recommendationDominates(slight,safer),false)});
test("a higher mean cannot dominate a materially better floor and ceiling",()=>{const base={nextPickAvailability:1,factors:{need:.42}},higherMean={...base,player:{position:"WR",mean:210,floor:90,ceiling:220}},completeProfile={...base,player:{position:"WR",mean:198,floor:155,ceiling:305}};assert.equal(recommendationDominates(higherMean,completeProfile),false);assert.equal(recommendationDominates(completeProfile,higherMean),false)});
test("FLEX depth dominance prefers Shaheed's stronger projection throughout a title-odds tie",()=>{const tied=(player,nextPickAvailability,planScore,need=.42)=>({player,nextPickAvailability,factors:{need},planScore,simulation:{interval:[.07,.10],championshipProbability:.081,rawProbability:.081,iterations:1000}}),shaheed=tied({id:"shaheed",name:"Rashid Shaheed",position:"WR",mean:145.9,floor:126,ceiling:195},.725,.2),tracy=tied({id:"tracy",name:"Tyrone Tracy",position:"RB",mean:114.6,floor:77,ceiling:167},.757,.9),sampson=tied({id:"sampson",name:"Dylan Sampson",position:"RB",mean:99.2,floor:82,ceiling:135},.95,.8);assert.equal(recommendationDominates(shaheed,tracy),true);assert.equal(recommendationDominates(shaheed,sampson),true);const ranked=rankEvaluatedRecommendations([tracy,sampson,shaheed]);assert.equal(ranked[0].player.name,"Rashid Shaheed");assert.ok(ranked.every(item=>item.simulation.displayTitleTenths===81))});
test("future-pick availability does not hide a materially superior FLEX player",()=>{const make=(player,nextPickAvailability,waitingForUserPick=false)=>({player,nextPickAvailability,waitingForUserPick,factors:{need:.42}}),better=make({name:"140-point WR",position:"WR",mean:140,floor:110,ceiling:180},.70),sampson=make({name:"Dylan Sampson",position:"RB",mean:90,floor:70,ceiling:125},.95);assert.equal(recommendationDominates(better,sampson),true);better.waitingForUserPick=true;sampson.waitingForUserPick=true;assert.equal(recommendationDominates(better,sampson),true)});
test("Stevenson's needed RB depth beats Kraft's backup-TE urgency in a title-odds tie",()=>{const simulation={interval:[.09,.13],championshipProbability:.111,rawProbability:.111,iterations:10000},kraft={player:{name:"Tucker Kraft",position:"TE",mean:170.5,floor:95,ceiling:261},nextPickAvailability:.18,waitingForUserPick:false,factors:{need:.24},planScore:.8,simulation},stevenson={player:{name:"Rhamondre Stevenson",position:"RB",mean:179.5,floor:146,ceiling:246},nextPickAvailability:.567,waitingForUserPick:false,factors:{need:.42},planScore:.7,simulation:{...simulation}};assert.equal(recommendationDominates(stevenson,kraft),true);assert.equal(rankEvaluatedRecommendations([kraft,stevenson])[0].player.name,"Rhamondre Stevenson");const requiredTe={...kraft,factors:{need:1}};assert.equal(recommendationDominates(stevenson,requiredTe),false);const eliteCeilingTe={...kraft,player:{...kraft.player,ceiling:310}};assert.equal(recommendationDominates(stevenson,eliteCeilingTe),false)});
test("cross-position FLEX dominance does not override a genuinely stronger positional need",()=>{const base={nextPickAvailability:1,planScore:.5,simulation:{interval:[.07,.10],championshipProbability:.081}},shaheed={...base,player:{position:"WR",mean:145.9,floor:126,ceiling:195},factors:{need:.42}},requiredRb={...base,player:{position:"RB",mean:114.6,floor:77,ceiling:167},factors:{need:1}};assert.equal(recommendationDominates(shaheed,requiredRb),false)});
test("an empty required RB room wins an unresolved Burden-Swift title tie",()=>{const simulation={interval:[.08,.12],championshipProbability:.096,rawProbability:.096,iterations:10000},burden={player:{id:"burden",name:"Luther Burden",position:"WR",mean:205.2,floor:137,ceiling:300},requiredStarterSlotsBefore:0,factors:{need:.72},planScore:.9,simulation},swift={player:{id:"swift",name:"D'Andre Swift",position:"RB",mean:206.3,floor:175,ceiling:278},requiredStarterSlotsBefore:2,factors:{need:1},planScore:.7,simulation:{...simulation}};assert.equal(recommendationDominates(swift,burden),true);const ranked=rankEvaluatedRecommendations([burden,swift],{strategy:"titleOnly"});assert.equal(ranked[0].player.id,"swift");assert.ok(ranked.every(item=>item.statisticalTie&&item.simulation.displayTitleTenths===96))});
test("Swift fills RB2 ahead of LaPorta depth after an early Loveland pick",()=>{const simulation={interval:[.08,.12],championshipProbability:.096,rawProbability:.096,iterations:10000},make=(id,name,position,mean,required,need,penalty,planScore)=>({player:{id,name,position,mean,floor:mean*(1-.4*.55),ceiling:mean*(1.25+.4*.35),performanceRisk:.4},requiredStarterSlotsBefore:required,starterFlexibilityPenalty:penalty,rosterCompletionPenalty:penalty,factors:{need},planScore,simulation:{...simulation}}),swift=make("swift","D'Andre Swift","RB",211.46,1,1,0,.8),laporta=make("laporta","Sam LaPorta","TE",187.9,0,.72,.6,.9);assert.equal(recommendationDominates(swift,laporta),true);const ranked=rankEvaluatedRecommendations([laporta,swift],{strategy:"titleOnly"});assert.equal(ranked[0].player.id,"swift");assert.ok(ranked.every(item=>item.statisticalTie&&item.simulation.displayTitleTenths===96))});
test("a marginal RB3 title estimate cannot override an empty WR starter",()=>{const make=(id,position,mean,floor,ceiling,required,penalty,planScore,p)=>({player:{id,name:id,position,mean,floor,ceiling},requiredStarterSlotsBefore:required,starterFlexibilityPenalty:penalty,rosterCompletionPenalty:penalty,factors:{need:required?1:.72},planScore,simulation:{interval:[p-.001,p+.001],championshipProbability:p,rawProbability:p,iterations:1_000_000,effectiveCandidateIterations:1_000_000}}),swift=make("swift","RB",212,175,278,0,.75,.1,.101),odunze=make("odunze","WR",213,140,300,1,0,.9,.095);assert.equal(flexibilityOverrideMargin(swift,odunze),.0075);const ranked=rankEvaluatedRecommendations([swift,odunze],{strategy:"titleOnly"});assert.deepEqual(ranked.map(item=>item.player.id),["odunze","swift"]);assert.ok(ranked.every(item=>item.statisticalTie&&item.simulation.displayTitleTenths===98))});
test("an exceptional RB3 title edge can override an empty WR starter",()=>{const make=(id,position,required,penalty,planScore,p)=>({player:{id,name:id,position,mean:position==="RB"?250:205,floor:position==="RB"?205:145,ceiling:position==="RB"?360:300},requiredStarterSlotsBefore:required,starterFlexibilityPenalty:penalty,rosterCompletionPenalty:penalty,factors:{need:required?1:.72},planScore,simulation:{interval:[p-.001,p+.001],championshipProbability:p,rawProbability:p,iterations:1_000_000,effectiveCandidateIterations:1_000_000}}),eliteRb=make("elite-rb","RB",0,.75,.1,.13),wr=make("open-wr","WR",1,0,.9,.095),ranked=rankEvaluatedRecommendations([wr,eliteRb],{strategy:"titleOnly"});assert.equal(ranked[0].player.id,"elite-rb");assert.ok(ranked[0].simulation.displayTitleTenths>ranked[1].simulation.displayTitleTenths)});
test("paired title evidence can select a FLEX player when rollout covers every open core starter",()=>{const burdenWins=new Uint8Array(10000),montgomeryWins=new Uint8Array(10000);burdenWins.fill(1,0,748);montgomeryWins.fill(1,0,748);burdenWins.fill(1,748,1128);montgomeryWins.fill(1,1128,1411);const make=(id,position,mean,required,penalty,planScore,p,wins,coverage=false)=>({player:{id,name:id,position,mean,floor:mean*.72,ceiling:mean*1.45},requiredStarterSlotsBefore:required,starterFlexibilityPenalty:penalty,rosterCompletionPenalty:penalty,conditionalRolloutCoreCoverage:coverage,factors:{need:required?1:.72},planScore,simulation:{interval:[p-.02,p+.02],championshipProbability:p,rawProbability:p,iterations:10000,effectiveCandidateIterations:10000,seed:202026,scenarioBankId:"holdout-pick-58",planScenarioWins:wins}}),burden=make("burden","WR",205,0,.75,.3,.1128,burdenWins,true),montgomery=make("montgomery","RB",193,1,0,1.1,.1031,montgomeryWins);assert.equal(flexibilityOverrideMargin(burden,montgomery),.0025);const ranked=rankEvaluatedRecommendations([montgomery,burden],{strategy:"titleOnly"});assert.deepEqual(ranked.map(item=>item.player.id),["burden","montgomery"]);assert.equal(ranked[0].statisticalTie,false);assert.ok(ranked[0].simulation.displayTitleTenths>ranked[1].simulation.displayTitleTenths)});
test("paired rollout coverage does not revive the marginal Swift-over-Odunze miss",()=>{const swiftWins=new Uint8Array(10000),odunzeWins=new Uint8Array(10000);swiftWins.fill(1,0,800);odunzeWins.fill(1,0,800);swiftWins.fill(1,800,1010);odunzeWins.fill(1,1010,1160);const make=(id,position,mean,required,penalty,planScore,p,wins,coverage=false)=>({player:{id,name:id,position,mean,floor:mean*.72,ceiling:mean*1.4},requiredStarterSlotsBefore:required,starterFlexibilityPenalty:penalty,rosterCompletionPenalty:penalty,conditionalRolloutCoreCoverage:coverage,factors:{need:required?1:.72},planScore,simulation:{interval:[p-.02,p+.02],championshipProbability:p,rawProbability:p,iterations:10000,effectiveCandidateIterations:10000,seed:202026,scenarioBankId:"swift-odunze-holdout",planScenarioWins:wins}}),swift=make("swift","RB",212,0,.75,.1,.101,swiftWins,true),odunze=make("odunze","WR",213,1,0,.9,.095,odunzeWins),ranked=rankEvaluatedRecommendations([swift,odunze],{strategy:"titleOnly"});assert.deepEqual(ranked.map(item=>item.player.id),["odunze","swift"]);assert.ok(ranked.every(item=>item.statisticalTie));assert.equal(ranked[0].simulation.displayTitleTenths,ranked[1].simulation.displayTitleTenths)});
test("tiny cross-position FLEX differences preserve scarcity and roster strategy",()=>{const base={nextPickAvailability:1,factors:{need:.42}},wr={...base,player:{position:"WR",mean:104,floor:82,ceiling:131}},rb={...base,player:{position:"RB",mean:100,floor:80,ceiling:130}};assert.equal(recommendationDominates(wr,rb),false)});
test("pick 128 integration keeps Shaheed first through simulation ranking",()=>{const state=shaheedPick128State(),prepared=recommend({state,userSlot:state.userSlot,limit:8}),evaluated=evaluateDraft({state,userSlot:state.userSlot,limit:8,iterations:300,seed:2026});assert.equal(prepared.length,8);assert.equal(prepared[0].player.name,"Rashid Shaheed");assert.ok(prepared.every(item=>item.waitingForUserPick&&item.availabilityTargetPick===128));assert.equal(evaluated[0].player.name,"Rashid Shaheed");assert.ok(evaluated.findIndex(item=>item.player.name==="Rashid Shaheed")<evaluated.findIndex(item=>item.player.name==="Tyrone Tracy"));assert.ok(evaluated.every(item=>item.statisticalTie&&item.simulation.displayTitleTenths===evaluated[0].simulation.displayTitleTenths))});
test("on-clock pick 128 quick evaluation guarantees Shaheed as the selected candidate",()=>{const state=shaheedPick128OnClockState(),evaluated=evaluateDraft({state,userSlot:state.userSlot,limit:8,iterations:120,seed:2026});assert.equal(state.picks.length,127);assert.equal(evaluated[0].player.name,"Rashid Shaheed");assert.ok(evaluated.every(item=>!item.waitingForUserPick&&item.simulation.candidateSelectionProbability===1))});
test("overlapping simulation uncertainty defers to the stable recommendation score",()=>{const make=(name,planScore,p)=>({player:{name,position:name,mean:100,floor:70,ceiling:130},nextPickAvailability:.5,factors:{need:.5},planScore,simulation:{interval:[.02,.18],championshipProbability:p}}),ranked=rankEvaluatedRecommendations([make("A",.3,.11),make("B",.8,.08)],{strategy:"upside"});assert.equal(ranked[0].player.name,"B")});test("evaluated recommendations respect dominance and uncertainty-aware scores",()=>{const result=evaluateDraft({state:fixtureState(),userSlot:1,iterations:40});for(let i=1;i<result.length;i++)assert.equal(recommendationDominates(result[i],result[i-1]),false)});
test("title-only supported noise cannot reverse a same-role projection sweep",()=>{const make=(id,p,planScore,mean,interval)=>({player:{id,name:id,position:"RB",mean,floor:mean-20,ceiling:mean+20},nextPickAvailability:.5,factors:{need:.5},planScore,simulation:{interval,championshipProbability:p}}),ranked=rankEvaluatedRecommendations([make("projection-favorite",.08,.99,200,[.07,.09]),make("title-favorite",.11,.01,100,[.10,.12])],{strategy:"titleOnly"});assert.equal(ranked[0].player.id,"projection-favorite");assert.ok(ranked.every(item=>item.statisticalTie&&item.simulation.evidenceStatus==="indistinguishable"));assert.equal(ranked[0].simulation.displayTitleTenths,ranked[1].simulation.displayTitleTenths)});
test("Jeanty's consensus sweep wins an unresolved title tier over Hampton",()=>{const make=(id,name,mean,p,planScore)=>({player:{id,name,position:"RB",mean,floor:mean*(1-.4*.55),ceiling:mean*(1.25+.4*.35),performanceRisk:.4},requiredStarterSlotsBefore:2,nextPickAvailability:.2,factors:{need:1},planScore,simulation:{interval:[p-.02,p+.02],championshipProbability:p,rawProbability:p,iterations:10000,effectiveCandidateIterations:10000}}),hampton=make("hampton","Omarion Hampton",262.62,.078,.9),jeanty=make("jeanty","Ashton Jeanty",269.02,.077,.8);assert.equal(recommendationDominates(jeanty,hampton),true);const ranked=rankEvaluatedRecommendations([hampton,jeanty],{strategy:"titleOnly"});assert.deepEqual(ranked.map(item=>item.player.id),["jeanty","hampton"]);assert.ok(ranked.every(item=>item.statisticalTie));assert.equal(ranked[0].simulation.displayTitleTenths,ranked[1].simulation.displayTitleTenths)});
test("title-only unresolved WR odds prefer Doubs over a materially lower projection",()=>{const make=(id,mean,floor,ceiling,p)=>({player:{id,name:id,position:"WR",mean,floor,ceiling},nextPickAvailability:.5,factors:{need:.42},planScore:.5,simulation:{interval:[.09,.13],championshipProbability:p,rawProbability:p,iterations:10000}}),higgins=make("Jayden Higgins",146.8,127,196,.1084),doubs=make("Romeo Doubs",167.4,142,226,.1076),ranked=rankEvaluatedRecommendations([higgins,doubs],{strategy:"titleOnly"});assert.equal(recommendationDominates(doubs,higgins),true);assert.equal(ranked[0].player.name,"Romeo Doubs");assert.ok(ranked.every(item=>item.statisticalTie));assert.equal(ranked[0].simulation.displayTitleTenths,ranked[1].simulation.displayTitleTenths);assert.equal(ranked[0].simulation.evidenceStatus,"indistinguishable")});
test("a supported noisy title estimate cannot rank a swept same-position player first",()=>{const make=(id,mean,floor,ceiling,p)=>({player:{id,name:id,position:"RB",mean,floor,ceiling},requiredStarterSlotsBefore:2,nextPickAvailability:.2,factors:{need:1},planScore:mean,simulation:{interval:[p-.001,p+.001],championshipProbability:p,rawProbability:p,iterations:10000,effectiveCandidateIterations:10000}}),cook=make("cook",270.6,233,362,.075),jeanty=make("jeanty",273.3,236,366,.072);assert.equal(recommendationDominates(jeanty,cook),true);for(const strategy of ["balanced","titleOnly"]){const ranked=rankEvaluatedRecommendations([cook,jeanty],{strategy});assert.deepEqual(ranked.map(item=>item.player.id),["jeanty","cook"]);assert.ok(ranked.every(item=>item.statisticalTie));assert.equal(ranked[0].simulation.displayTitleTenths,ranked[1].simulation.displayTitleTenths)}});
test("dominance-safe title tiers cover depth and cross-FLEX candidates",()=>{const make=(id,position,mean,floor,ceiling,need,p)=>({player:{id,name:id,position,mean,floor,ceiling},requiredStarterSlotsBefore:0,nextPickAvailability:.5,factors:{need},planScore:mean,simulation:{interval:[p-.001,p+.001],championshipProbability:p,rawProbability:p,iterations:10000,effectiveCandidateIterations:10000}}),pairs=[[make("strong-depth","RB",220,180,300,.42,.07),make("weak-depth","RB",190,150,260,.42,.10)],[make("strong-flex","WR",250,200,330,.6,.07),make("weak-flex","RB",200,160,280,.5,.10)]];for(const [superior,inferior] of pairs){assert.equal(recommendationDominates(superior,inferior),true);for(const strategy of ["balanced","titleOnly"]){for(const input of [[superior,inferior],[inferior,superior]]){const ranked=rankEvaluatedRecommendations(input,{strategy});assert.ok(ranked.indexOf(ranked.find(item=>item.player.id===superior.player.id))<ranked.indexOf(ranked.find(item=>item.player.id===inferior.player.id)));assert.equal(ranked.find(item=>item.player.id===superior.player.id).simulation.displayTitleTenths,ranked.find(item=>item.player.id===inferior.player.id).simulation.displayTitleTenths)}}}});
test("multi-card evidence witnesses cannot create increasing displayed title tiers",()=>{const make=(id,position,mean,p,interval,planScore)=>({player:{id,name:id,position,mean,floor:mean*.8,ceiling:mean*1.2},nextPickAvailability:.5,factors:{need:.5},planScore,simulation:{interval,championshipProbability:p}}),strong=make("strong","RB",200,.07,[.05,.11],.7),witness=make("witness","QB",300,.12,[.099,.15],.9),weak=make("weak","RB",100,.10,[.07,.098],.1),ranked=rankEvaluatedRecommendations([weak,witness,strong],{strategy:"titleOnly"});assert.equal(recommendationDominates(strong,weak),true);assert.ok(ranked.findIndex(item=>item.player.id==="strong")<ranked.findIndex(item=>item.player.id==="weak"));for(let index=1;index<ranked.length;index++)assert.ok(ranked[index-1].simulation.displayTitleTenths>=ranked[index].simulation.displayTitleTenths);assert.equal(ranked.find(item=>item.player.id==="strong").simulation.displayTitleTenths,ranked.find(item=>item.player.id==="weak").simulation.displayTitleTenths)});
test("transitive dominance is permutation-invariant under reversed raw title estimates",()=>{const make=(id,mean,p)=>({player:{id,name:id,position:"RB",mean,floor:mean-30,ceiling:mean+50},nextPickAvailability:.5,factors:{need:.5},planScore:mean,simulation:{interval:[p-.001,p+.001],championshipProbability:p,rawProbability:p,iterations:10000,effectiveCandidateIterations:10000}}),a=make("a",300,.07),b=make("b",250,.08),c=make("c",200,.09),permutations=[[a,b,c],[a,c,b],[b,a,c],[b,c,a],[c,a,b],[c,b,a]];for(const strategy of ["balanced","titleOnly"])for(const input of permutations){const ranked=rankEvaluatedRecommendations(input,{strategy});assert.deepEqual(ranked.map(item=>item.player.id),["a","b","c"]);assert.equal(new Set(ranked.map(item=>item.simulation.displayTitleTenths)).size,1)}});
test("Odunze ranks ahead of Pierce when title odds are indistinguishable",()=>{const make=(player,p,planScore,risk)=>({player:{...player,risk},nextPickAvailability:.7,waitingForUserPick:true,factors:{need:.42,risk},planScore,simulation:{interval:[.09,.13],championshipProbability:p}}),odunze=make({id:"11620",name:"Rome Odunze",position:"WR",mean:204.26,floor:159.7,ceiling:283.7},.1077,.8,.397),pierce=make({id:"8142",name:"Alec Pierce",position:"WR",mean:199.28,floor:165.4,ceiling:270.7},.1083,.7,.8),ranked=rankEvaluatedRecommendations([pierce,odunze],{strategy:"titleOnly"});assert.equal(recommendationDominates(odunze,pierce),false);assert.equal(ranked[0].player.name,"Rome Odunze");assert.ok(ranked.every(item=>item.statisticalTie&&item.simulation.displayTitleTenths===108))});
test("title-only exact ties use the championship-upside plan instead of player id",()=>{const make=(id,planScore)=>({player:{id,name:id,position:"RB",mean:100,floor:60,ceiling:180},nextPickAvailability:.5,factors:{need:.5},planScore,simulation:{interval:[.08,.12],championshipProbability:.1,rawProbability:.1}}),ranked=rankEvaluatedRecommendations([make("aaa-id-only",.2),make("zzz-upside-plan",.9)],{strategy:"titleOnly"});assert.equal(ranked[0].player.id,"zzz-upside-plan");assert.equal(ranked[0].simulation.championshipProbability,.1)});
test("overlapping neighbors cannot chain a supported loser into the leader's title tie",()=>{const make=(id,p,interval,planScore)=>({player:{id,name:id,position:id,mean:100,floor:80,ceiling:120},nextPickAvailability:.5,factors:{need:.5},planScore,simulation:{interval,championshipProbability:p}}),items=[make("leader",.13,[.115,.145],.1),make("bridge",.12,[.105,.135],.2),make("supported-loser",.10,[.085,.114],1)];for(const strategy of ["titleOnly","balanced"]){const ranked=rankEvaluatedRecommendations(items,{strategy});assert.equal(ranked.at(-1).player.id,"supported-loser");assert.ok(ranked[0].simulation.displayTitleTenths>ranked.at(-1).simulation.displayTitleTenths)}});

test("upside rewards performance volatility, never injury status",()=>{const settings={teams:2,rounds:2,slots:{QB:0,RB:0,WR:1,TE:0,FLEX:0,K:0,DST:0,BENCH:1}},player=(id,risk)=>({id,name:id,position:"WR",team:"T",mean:200,floor:150,ceiling:260,risk,performanceRisk:.3,scarcity:.4,adp:1,adpSd:8,eligibleForRecommendation:true}),healthy=player("healthy",.3),injured=player("injured",.8),state={platform:"fixture",draftId:"injury-direction",settings,players:[healthy,injured],picks:[],projectionSeason:2026},upside=recommend({state,userSlot:1,strategy:"upside",limit:100}),safe=recommend({state,userSlot:1,strategy:"safe",limit:100}),byId=rows=>new Map(rows.map(row=>[row.player.id,row]));assert.equal(byId(upside).get("healthy").factors.risk,byId(upside).get("injured").factors.risk);assert.ok(byId(safe).get("injured").factors.risk>byId(safe).get("healthy").factors.risk);assert.ok(byId(safe).get("injured").planScore<byId(safe).get("healthy").planScore)});
test("repeated evaluations reuse candidate simulations",()=>{const state=fixtureState(),first=evaluateDraft({state,userSlot:1,positions:["RB"],iterations:30}),second=evaluateDraft({state,userSlot:1,positions:["RB"],iterations:30}),firstById=new Map(first.map(item=>[item.player.id,item]));assert.deepEqual(second.map(x=>x.simulation),first.map(x=>x.simulation));for(const item of second)assert.strictEqual(item.simulation.scenarioWins,firstById.get(item.player.id).simulation.scenarioWins)});
test("simulation source includes historical position-level projection error",()=>{const source=fs.readFileSync(new URL("../core/simulate.js",import.meta.url),"utf8");assert.match(source,/WEEKLY_PROJECTION_RMSE/);assert.match(source,/6\.6749/);assert.match(source,/lineupWeeklyError/)});

test("opening round in a one-QB league is driven by positional value, not raw QB points",()=>{const settings={teams:10,rounds:15,slots:{QB:1,RB:2,WR:2,TE:1,FLEX:1,K:1,DST:1,BENCH:6}},players=[],add=(position,count,start,step,adpStart)=>{for(let i=0;i<count;i++){const mean=start-i*step;players.push({id:`${position}${i}`,name:`${position} ${i}`,position,mean,ceiling:mean*1.2,floor:mean*.72,risk:.2,scarcity:.3,adp:adpStart+i,adpSd:8,eligibleForRecommendation:true})}};add("QB",20,380,8,31);add("RB",50,310,6,1);add("WR",50,300,5.5,2);add("TE",20,240,7,35);add("K",12,140,2,130);add("DST",12,135,2,125);const result=recommend({state:{settings,players,picks:[]},userSlot:1,limit:8});assert.ok(result.some(x=>["RB","WR"].includes(x.player.position)));assert.ok(result.filter(x=>x.player.position==="QB").length<=1);assert.ok(result.every(x=>Number.isFinite(x.valueOverReplacement)&&Number.isFinite(x.replacementPoints)))});
test("replacement value is stable when the UI position filter changes",()=>{const state=fixtureState(),all=recommend({state,userSlot:1,limit:100}),qbs=recommend({state,userSlot:1,positions:["QB"],limit:100});for(const qb of qbs){const baseline=all.find(x=>x.player.id===qb.player.id);if(baseline)assert.equal(qb.valueOverReplacement,baseline.valueOverReplacement)}});
test("superflex correctly increases quarterback replacement demand",()=>{const one={teams:10,slots:{QB:1,RB:2,WR:2,TE:1,FLEX:1}},superflex={teams:10,slots:{QB:1,RB:2,WR:2,TE:1,FLEX:1,SUPER_FLEX:1}};assert.ok(replacementDemand("QB",superflex)>replacementDemand("QB",one))});
test("value over replacement compares a player only with his own position",()=>{const settings={teams:2,slots:{QB:1,RB:1}},pool=[{position:"QB",mean:300},{position:"QB",mean:280},{position:"QB",mean:260},{position:"RB",mean:220},{position:"RB",mean:150},{position:"RB",mean:100}],qb=pool[0],rb=pool[3];assert.equal(valueOverReplacement(qb,pool,settings).value,40);assert.equal(valueOverReplacement(rb,pool,settings).value,120)});
test("replacement demand shrinks as players at that position leave the board",()=>{const state=fixtureState({teams:4,picked:0}),runningBacks=state.players.filter(player=>player.position==="RB");state.settings.slots={...state.settings.slots,RB:1,FLEX:0};const total=replacementDemand("RB",state.settings);state.picks=runningBacks.slice(0,2).map((player,index)=>({pickNo:index+1,playerId:player.id,slot:index+1}));assert.equal(remainingReplacementDemand("RB",state),total-2);const pool=runningBacks.slice(2,7),candidate=pool[0],correct=valueOverReplacement(candidate,pool,state.settings,"mean",remainingReplacementDemand("RB",state)),stale=valueOverReplacement(candidate,pool,state.settings,"mean",total);assert.ok(correct.value<stale.value)});
test("off-turn title odds measure unconditional player quality in every scenario",()=>{const iterations=200,result=evaluateDraft({state:fixtureState({teams:4,picked:1}),userSlot:1,iterations});assert.ok(result.every(x=>x.simulation.conditional&&x.simulation.effectiveCandidateIterations===iterations&&x.simulation.candidateSelectionProbability===1&&Number.isFinite(x.simulation.planChampionshipProbability)));assert.ok(result.some(x=>x.nextPickAvailability<1))});
test("off-turn ranking maximizes unconditional player quality and preserves availability separately",()=>{const make=(id,quality,survival,plan,planScore)=>({player:{id,name:id,position:"RB",mean:100,floor:70,ceiling:130},nextPickAvailability:survival,waitingForUserPick:true,factors:{need:.5},planScore,simulation:{championshipProbability:quality,rawProbability:quality,conditionalChampionshipProbability:quality,conditionalRawProbability:quality,planChampionshipProbability:plan,planRawProbability:plan,candidateSelectionProbability:1,interval:[quality-.001,quality+.001]}}),items=[make("unlikely elite",.16,.1,.09,.2),make("realistic target",.14,.9,.135,.8)];for(const strategy of ["balanced","titleOnly"]){const ranked=rankEvaluatedRecommendations(items,{strategy});assert.equal(ranked[0].player.id,"unlikely elite");assert.equal(ranked[0].simulation.championshipProbability,.16);assert.equal(ranked[0].nextPickAvailability,.1);assert.equal(ranked[1].simulation.championshipProbability,.14)}});
test("balanced ranking primarily follows conservative title probability",()=>{const make=(name,p,interval,planScore)=>({player:{name,position:name,mean:100,floor:70,ceiling:130},nextPickAvailability:.5,factors:{need:.5},planScore,simulation:{interval,championshipProbability:p}}),ranked=rankEvaluatedRecommendations([make("projection favorite",.12,[.11,.13],.9),make("title favorite",.16,[.15,.17],.1)],{strategy:"balanced"});assert.equal(ranked[0].player.name,"title favorite")});
test("unsupported one-tenth-point differences collapse to one displayed percentage",()=>{const make=(name,p,planScore)=>({player:{id:name,name,position:name,mean:100,floor:70,ceiling:130},nextPickAvailability:.5,factors:{need:.5},planScore,simulation:{interval:[.08,.12],championshipProbability:p}}),ranked=rankEvaluatedRecommendations([make("higher stable score",.100,.9),make("higher raw estimate",.101,.1)],{strategy:"balanced"});assert.equal(ranked[0].player.name,"higher stable score");assert.equal(ranked[0].simulation.displayTitleTenths,ranked[1].simulation.displayTitleTenths);assert.equal(ranked[0].simulation.evidenceStatus,"indistinguishable")});
test("every distinct displayed title percentage has supported directional evidence",()=>{const make=(name,p,interval)=>({player:{id:name,name,position:name,mean:100,floor:70,ceiling:130},nextPickAvailability:.5,factors:{need:.5},planScore:p,simulation:{interval,championshipProbability:p}}),ranked=rankEvaluatedRecommendations([make("13.1",.131,[.129,.133]),make("13.0",.130,[.128,.132]),make("clearly lower",.10,[.098,.102])],{strategy:"balanced"});assert.equal(ranked[0].simulation.displayTitleTenths,ranked[1].simulation.displayTitleTenths);assert.ok(ranked[1].simulation.displayTitleTenths>ranked[2].simulation.displayTitleTenths);assert.equal(ranked[2].simulation.evidenceStatus,"supported")});
test("evidence boundaries move an uncertain dominated card below the supported adjacent witness",()=>{const make=(id,position,mean,championshipProbability,rawProbability,iterations,planScore)=>({player:{id,name:id,position,mean,floor:mean*.8,ceiling:mean*1.2},nextPickAvailability:.5,factors:{need:.5},planScore,simulation:{interval:[.06,.16],championshipProbability,rawProbability,iterations,effectiveCandidateIterations:iterations}}),projectionLeader=make("projection leader","RB",200,.14,.14,10000,.9),noisyDominated=make("noisy dominated","RB",100,.15,.12,100,.8),supportedLower=make("supported lower","QB",90,.08,.08,10000,.1),ranked=rankEvaluatedRecommendations([noisyDominated,supportedLower,projectionLeader],{strategy:"balanced"});assert.deepEqual(ranked.map(item=>item.player.id),["projection leader","supported lower","noisy dominated"]);assert.ok(ranked[0].simulation.displayTitleTenths>ranked[1].simulation.displayTitleTenths);assert.equal(ranked[1].simulation.displayTitleTenths,ranked[2].simulation.displayTitleTenths);assert.ok(ranked.findIndex(item=>item.player.id==="projection leader")<ranked.findIndex(item=>item.player.id==="noisy dominated"))});
test("early-round general recommendations reject obvious market reaches",()=>{const settings={teams:10,rounds:15,slots:{QB:1,RB:2,WR:2,TE:1,FLEX:1,K:1,DST:1,BENCH:6}},players=[];for(let i=0;i<30;i++)players.push({id:`WR${i}`,name:`WR ${i}`,position:"WR",mean:250-i,ceiling:300-i,floor:190-i,risk:.3,scarcity:.3,adp:i+1,adpSd:8,eligibleForRecommendation:true});for(let i=0;i<12;i++)players.push({id:`TE${i}`,name:`TE ${i}`,position:"TE",mean:245-i,ceiling:310-i,floor:170-i,risk:.4,scarcity:.7,adp:70+i,adpSd:8,eligibleForRecommendation:true});const result=recommend({state:{platform:"fixture",draftId:"reach",settings,players,picks:[]},userSlot:1,limit:8});assert.ok(result.length>0);assert.ok(result.every(item=>item.player.position!=="TE"));assert.ok(result.every(item=>Number(item.player.adp)<=16))});
test("an obvious projection outlier cannot be hidden outside the early ADP window",()=>{const settings={teams:10,rounds:15,slots:{QB:0,RB:0,WR:2,TE:0,FLEX:1,K:0,DST:0,BENCH:12}},player=(id,mean,adp)=>({id,name:id,position:"WR",mean,floor:mean*.78,ceiling:mean*1.22,risk:.25,scarcity:.35,adp,adpSd:8,eligibleForRecommendation:true}),market=Array.from({length:20},(_,index)=>player(`market-${index}`,250-index,index+1)),outlier=player("projection-outlier",340,100),ordinaryReach=player("ordinary-reach",245,101),result=recommend({state:{platform:"fixture",draftId:"projection-frontier",settings,players:[...market,outlier,ordinaryReach],picks:[],projectionSeason:2026},userSlot:1,limit:8});assert.equal(result[0].player.id,outlier.id);assert.equal(result.some(item=>item.player.id===ordinaryReach.id),false)});
test("deep asymmetric ceiling bets stay inspectable even when outside the strict simulated top five",()=>{const settings={teams:10,rounds:15,slots:{QB:0,RB:1,WR:2,TE:0,FLEX:1,K:0,DST:0,BENCH:11}},player=(id,mean,ceiling,adp,floor=mean*.8,position="WR")=>({id,name:id,position,mean,floor,ceiling,risk:.4,scarcity:.35,adp,adpSd:8,eligibleForRecommendation:true}),market=Array.from({length:20},(_,index)=>player(`market-${index}`,260-index,310-index,index+1)),rb=player("rb-plan",240,300,4,190,"RB"),pureCeiling=[player("ceiling-one",245,520,100,190),player("ceiling-two",244,510,101,189)],asymmetric=player("asymmetric-breakout",100,500,150,20),state={platform:"fixture",draftId:"title-frontier",settings,players:[...market,rb,...pureCeiling,asymmetric],picks:[],projectionSeason:2026},board=buildCandidateBoard({state,userSlot:1,strategy:"titleOnly"}),shortlist=recommend({state,userSlot:1,strategy:"titleOnly",limit:5});assert.equal(shortlist.length,5);for(const id of ["ceiling-one","ceiling-two","asymmetric-breakout"])assert.ok(board.some(row=>row.player.id===id));assert.deepEqual(shortlist.map(row=>row.player.id),board.filter(row=>row.simulationEligible).slice(0,5).map(row=>row.player.id))});
test("title-only discovery never spends the last required roster pick on upside depth",()=>{const state=completionState({rounds:7,slots:{QB:1,RB:1,WR:1,TE:1,FLEX:0,K:1,DST:1,BENCH:0},rosterPositions:["QB","RB","WR","TE","DST","RB"]}),result=recommend({state,userSlot:1,strategy:"titleOnly",limit:5});assert.ok(result.length>0);assert.ok(result.every(item=>item.player.position==="K"&&item.rosterCompletionRequired))});
test("ADP timing cannot overwhelm a projection edge after candidates clear the market window",()=>{const settings={teams:10,rounds:15,slots:{QB:1,RB:2,WR:2,TE:1,FLEX:1,K:0,DST:0,BENCH:8}},player=(id,mean,adp)=>({id,name:id,position:"WR",mean,floor:mean*.75,ceiling:mean*1.25,risk:.25,scarcity:.4,adp,adpSd:8,eligibleForRecommendation:true}),players=[player("projection edge",320,16),player("market favorite",250,1),...Array.from({length:25},(_,i)=>player(`depth ${i}`,240-i,2+i))],result=recommend({state:{platform:"fixture",draftId:"edge",settings,players,picks:[],projectionSeason:2026},userSlot:1,limit:100}),edge=result.find(item=>item.player.id==="projection edge"),market=result.find(item=>item.player.id==="market favorite");assert.ok(edge&&market);assert.ok(edge.marketReachPenalty<=.16);assert.ok(result.indexOf(edge)<result.indexOf(market))});
test("pick 32 look-ahead ranks Garrett Wilson over Travis Etienne without future picks",()=>{const settings={teams:12,rounds:16,slots:{QB:1,RB:2,WR:2,TE:1,FLEX:1,K:1,DST:1,BENCH:7}},player=(id,name,position,mean,adp)=>({id,name,position,mean,floor:mean*.72,ceiling:mean*1.28,risk:.35,scarcity:.4,adp,adpSd:8,eligibleForRecommendation:true}),amon=player("amon","Amon-Ra St. Brown","WR",324.3,8),hampton=player("hampton","Omarion Hampton","RB",279.3,17),wilson=player("wilson","Garrett Wilson","WR",257.3,35),etienne=player("etienne","Travis Etienne","RB",241.3,32),picks=Array.from({length:31},(_,index)=>{const pickNo=index+1;return{pickNo,playerId:pickNo===8?amon.id:pickNo===17?hampton.id:`drafted-${pickNo}`,slot:snakeSlot(pickNo,12)}}),ranked=recommend({state:{settings,players:[amon,hampton,wilson,etienne],picks,projectionSeason:2026},userSlot:8,limit:100});assert.ok(ranked.some(item=>item.player.id===wilson.id)&&ranked.some(item=>item.player.id===etienne.id));assert.ok(ranked.findIndex(item=>item.player.id===wilson.id)<ranked.findIndex(item=>item.player.id===etienne.id));assert.ok(ranked.find(item=>item.player.id===wilson.id).lookAheadBonus>ranked.find(item=>item.player.id===etienne.id).lookAheadBonus)});
test("an explicit position filter still allows users to inspect later tight ends",()=>{const state=fixtureState({picked:0});for(let i=0;i<state.players.length;i++)if(state.players[i].position==="TE")state.players[i].adp=100+i;const result=recommend({state,userSlot:1,positions:["TE"],limit:100});assert.ok(result.length>0);assert.ok(result.every(item=>item.player.position==="TE"))});
