test("pick 63 title-only discovery preserves the raw FLEX ceiling leader",()=>{const settings={teams:12,rounds:16,slots:{QB:1,RB:2,WR:2,TE:1,FLEX:1,K:1,DST:1,BENCH:7}},player=(id,name,position,mean,floor,ceiling,scarcity=.4,adp=70,risk=.4)=>({id,name,position,mean,floor,ceiling,risk,scarcity,adp,adpSd:10,eligibleForRecommendation:true}),roster=[player("rb1","RB 1","RB",270,220,360,.7,10),player("rb2","RB 2","RB",260,210,350,.7,15),player("qb","QB","QB",368,300,496,.6,34),player("rb3","RB 3","RB",220,160,315,.6,39),player("wr1","WR 1","WR",220,160,310,.4,58)],pierce=player("pierce","Alec Pierce","WR",194.85,109.12,298.12,.55,70,.8),candidates=[pierce,player("pitts","Kyle Pitts","TE",185.17,145,247.66,.7,71),player("montgomery","David Montgomery","RB",193.32,155,258.57,.6,63),player("laporta","Sam LaPorta","TE",187.52,120,286.91,.7,77),player("evans","Mike Evans","WR",194.54,150,278.24,.4,73),player("metcalf","DK Metcalf","WR",189.68,145,257.61,.4,72),player("washington","Parker Washington","WR",188.97,142,254.67,.4,83),player("sutton","Courtland Sutton","WR",187.23,145,250.42,.4,74),player("warren","Jaylen Warren","RB",185.67,145,250.22,.5,80)],userPickNos=[10,15,34,39,58],picks=Array.from({length:62},(_,index)=>{const pickNo=index+1,userIndex=userPickNos.indexOf(pickNo);return{pickNo,playerId:userIndex>=0?roster[userIndex].id:`taken-${pickNo}`,slot:snakeSlot(pickNo,12)}}),state={platform:"fixture",draftId:"pierce-pick-63",settings,players:[...roster,...candidates],picks,projectionSeason:2026},shortlist=recommend({state,userSlot:10,strategy:"titleOnly",limit:8});assert.ok(shortlist.some(item=>item.player.id===pierce.id),`shortlist was ${shortlist.map(item=>item.player.name).join(", ")}`)});
test("elite specialists can clear the conservative opportunity-cost hurdle",()=>{const roster=[{id:"qb",position:"QB",mean:300},{id:"rb",position:"RB",mean:220},{id:"wr",position:"WR",mean:210},{id:"te",position:"TE",mean:170}],settings={teams:4,slots:{QB:1,RB:1,WR:1,TE:1,FLEX:0,K:1,DST:0}},elite={id:"elite",position:"K",mean:180,floor:140,risk:.3},replacement={id:"replacement",position:"K",mean:130,floor:95,risk:.3},bench={id:"bench",position:"WR",mean:205,floor:150,risk:.3},result=specialistOpportunity({player:elite,pool:[elite,replacement,bench],roster,settings});assert.equal(result.eligible,true);assert.equal(result.replacementDelta,50);assert.ok(result.uncertaintyAdjustedDelta>result.hurdle)});
test("flat specialist tiers remain late-round options",()=>{const roster=[{id:"qb",position:"QB",mean:300},{id:"rb",position:"RB",mean:220},{id:"wr",position:"WR",mean:210},{id:"te",position:"TE",mean:170}],settings={teams:4,slots:{QB:1,RB:1,WR:1,TE:1,FLEX:0,K:1,DST:0}},one={id:"one",position:"K",mean:145,floor:105,risk:.4},two={id:"two",position:"K",mean:140,floor:102,risk:.4},result=specialistOpportunity({player:one,pool:[one,two],roster,settings});assert.equal(result.eligible,false);assert.ok(result.uncertaintyAdjustedDelta<result.hurdle)});
test("simulation-only specialist short circuit preserves eligibility",()=>{const roster=[{id:"qb",position:"QB",mean:300},{id:"rb",position:"RB",mean:220},{id:"wr",position:"WR",mean:210},{id:"te",position:"TE",mean:170}],settings={teams:4,slots:{QB:1,RB:1,WR:1,TE:1,FLEX:0,K:1,DST:0}},replacement={id:"replacement",position:"K",mean:130,floor:95,risk:.3},bench={id:"bench",position:"WR",mean:205,floor:150,risk:.3};for(const player of [{id:"flat",position:"K",mean:145,floor:105,risk:.4},{id:"elite",position:"K",mean:180,floor:140,risk:.3}]){const input={player,pool:[player,replacement,bench],roster,settings},full=specialistOpportunity(input),optimized=specialistOpportunity({...input,eligibilityOnly:true});assert.equal(optimized.eligible,full.eligible);assert.equal(optimized.uncertaintyAdjustedDelta,full.uncertaintyAdjustedDelta)}});
test("early recommendations value the starter quality preserved for the following turn",()=>{const settings={teams:12,rounds:16,slots:{QB:1,RB:2,WR:2,TE:1,FLEX:1,K:0,DST:0,BENCH:9},scoring:{reception:1}},player=(id,position,mean,ceiling,adp)=>({id,name:id,position,mean,floor:mean*.72,ceiling,risk:.4,scarcity:.5,adp,adpSd:8,eligibleForRecommendation:true}),rb1=player("RB one","RB",290,390,10),rb2=player("second RB","RB",268,365,15),wr1=player("scarce WR","WR",263,390,16),rbFallback=player("RB fallback","RB",235,335,36),wrFallback=player("WR cliff","WR",175,225,25),qb=player("QB","QB",360,450,35),te=player("TE","TE",200,280,40),players=[rb1,rb2,wr1,rbFallback,wrFallback,qb,te,...Array.from({length:12},(_,index)=>player(`depth-${index}`,index%2?"RB":"WR",160-index*2,215-index*2,45+index))],picks=Array.from({length:14},(_,index)=>({pickNo:index+1,playerId:index===9?rb1.id:`taken-${index+1}`,slot:snakeSlot(index+1,12)})),state={platform:"fixture",draftId:"early-optionality",projectionSeason:2026,settings,players,picks},ranked=recommend({state,userSlot:10,strategy:"titleOnly",limit:8}),rb=ranked.find(item=>item.player.id===rb2.id),wr=ranked.find(item=>item.player.id===wr1.id);assert.ok(rb&&wr);assert.equal(wr.optionalityTargetPick,34);assert.ok(wr.futureStarterAccess>rb.futureStarterAccess,`WR ${wr.futureStarterAccess} RB ${rb.futureStarterAccess}`);assert.ok(wr.optionalityBonus>rb.optionalityBonus);assert.ok(ranked.indexOf(wr)<ranked.indexOf(rb))});
test("calibration strength is fixed rather than mechanically changing with draft progress",()=>{const early=calibrateTitleProbability({wins:100,iterations:1000,teams:10,progress:0}),late=calibrateTitleProbability({wins:100,iterations:1000,teams:10,progress:1});assert.equal(early.priorStrength,late.priorStrength);assert.equal(early.championshipProbability,late.championshipProbability)});
